@startuml

class Provider {
  + name : string
  + location : string
}

class Cruise {
  + number : int
  + name : string
  + startDate : date
  + endDate : date
}

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Guest {
  + name : string
  + isVIP : boolean
}

class Ship {
  + name : string
  + deckCount : int
  + length : float
  + passengerCount : int
}

class TravelAgency {
  + name : string
  + address : string
}

class Booking {
  + bookingNumber : int
  + bookingDate : date
}

class DestinationArea {
  + name : string
  + seaName : string
}

class Show {
  + title : string
  + duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise : organizes
Cruise "*" -- "*" Employee : requires
Cruise "*" -- "*" Guest : has
Cruise "*" -- "1" Ship : uses
Cruise "1" -- "*" Booking : is booked through
TravelAgency "1" -- "*" Booking : manages
Cruise "*" -- "1" DestinationArea : heads for
Cruise "1" -- "*" Show : offers
Cruise "1" -- "*" Ticket : issues
Guest "1" -- "0..1" Ticket : has
Ticket "*" -- "1" Cruise : belongs to

@enduml

